class Solution {
public:
    int maximumLengthSubstring(string s) {
        int cnt[26] = {0};
        int left = 0, ans = 0;
        for (int right = 0; right < (int)s.size(); right++) {
            int idx = s[right] - 'a';
            cnt[idx]++;
            while (cnt[idx] > 2) {
                cnt[s[left] - 'a']--;
                left++;
            }
            if (right - left + 1 > ans) ans = right - left + 1;
        }
        return ans;
    }
};
